import { SheetBody } from '../../slots/defs/sheet';
import { STATUSES, active as isActive, reviewLate, useClaims } from '../claims/claims';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDueTotal, usePeriods } from '../periods/periods';
import { diffDue, personDueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate, useReviewSla } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { useVoidReasons } from '../voidreasons/voidreasons';

/** The sheet's summary, every figure as the list shows it: per grade the people on it today (those retired left
 *  out, whatever their retire date) and their due-totals added up (skipping n/a), per period its
 *  due-total and its change from the period before it by start date (none for the earliest), how many of them are active (see claims' active), and per status how many of the sheet's claims have it, and how many REVIEW claims are review-late (see reviewLate), and per void reason on the list how many VOID claims were
 *  voided with it. */
function Summary({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const reviewSla = useReviewSla(sheetId);
  const voidReasons = useVoidReasons(sheetId).data ?? [];
  const active = people.filter((p) => p.retiredFrom === null);
  const periodTotals = new Map(periods.map((p) => [p.name, periodDueTotal(p, claims, people, rates, floor, late)]));
  const byStart = [...periods].sort((a, b) => a.from.localeCompare(b.from));
  const periodChange = new Map(byStart.map((p, i) => [p.name, i === 0 ? ''
    : diffDue(periodTotals.get(p.name)!, periodTotals.get(byStart[i - 1].name)!)]));

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g} data-testid={`summary-grade-${g}`}>
                <th>Grade {g}</th>
                <td>
                  People <span data-testid={`summary-grade-${g}-count`}>{onGrade.length}</span>
                </td>
                <td>
                  Due total{' '}
                  <span data-testid={`summary-grade-${g}-due-total`}>
                    {sumDue(onGrade.map((p) => personDueTotal(p, claims, rates, today, floor, late, cap)))}
                  </span>
                </td>
                <td>
                  Active{' '}
                  <span data-testid={`summary-grade-${g}-active`}>
                    {onGrade.filter((p) => isActive(p, claims, today)).length}
                  </span>
                </td>
              </tr>
            );
          })}
          {periods.map((p) => (
            <tr key={p.name} data-testid={`summary-period-${p.name}`}>
              <th>Period {p.name}</th>
              <td>
                Due total{' '}
                <span data-testid={`summary-period-${p.name}-due-total`}>
                  {periodTotals.get(p.name)}
                </span>
              </td>
              <td>
                Change <span data-testid={`summary-period-${p.name}-change`}>{periodChange.get(p.name)}</span>
              </td>
            </tr>
          ))}
          {STATUSES.map((s) => (
            <tr key={s} data-testid={`summary-status-${s}`}>
              <th>{s}</th>
              <td>
                Claims <span data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</span>
              </td>
            </tr>
          ))}
          <tr data-testid="summary-review-late">
            <th>Review late</th>
            <td>
              Claims{' '}
              <span data-testid="summary-review-late-count">
                {claims.filter((c) => reviewLate(c, today, reviewSla)).length}
              </span>
            </td>
          </tr>
          {voidReasons.map((r) => (
            <tr key={r.id} data-testid={`summary-void-${r.reason}`}>
              <th>Voided: {r.reason}</th>
              <td>
                Claims <span data-testid={`summary-void-${r.reason}-count`}>{r.voided}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 23, Component: Summary });
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheet';
import { STATUSES, type Claim } from '../claims/claims';
import { GRADES, gradeOn, type Person } from '../people/people';
import { overdueDues, personDueTotal, sumDue, trimmedSum, type Rate } from '../rates/rates';
import { floorOf, lateOf, type Settings } from '../settings/settings';
import { useAsOf, type Sheet } from '../sheet/sheet';

/** One read of a sheet as the store holds it now, or (asOf given, yyyy-mm-dd) as it stood at the end of that day,
 *  whatever date this screen shows its own sheet as of. Keyed under the sheet, so a load of that sheet re-reads it. */
function useNow<T>(sheetId: string, part: string, asOf = '') {
  return useQuery({
    queryKey: ['sheet', sheetId, 'now', part, asOf],
    queryFn: () => getJsonNow<T>(`/api/sheets/${encodeURIComponent(sheetId)}${part === '' ? '' : `/${part}`}`
      + (asOf === '' ? '' : `?asOf=${encodeURIComponent(asOf)}`)),
  });
}

/** The tree's figures gathered so far: per person (in sheet order) their names (name and aliases), due-total and
 *  overdue-total, and the per-grade and per-status figures added up. */
type Figures = { names: string[][]; dues: string[]; overdues: string[]; grades: Record<string, string>;
  statuses: Record<string, number> };

const NONE: Figures = {
  names: [], dues: [], overdues: [],
  grades: Object.fromEntries(GRADES.map((g) => [g, '0.00'])),
  statuses: Object.fromEntries(STATUSES.map((s) => [s, 0])),
};

/** Adds the figures of sheets[at] to `sum`, then goes on to the next sheet; past the last, shows the figures added
 *  up. One component per sheet keeps each sheet's reads in hooks of its own. */
function Accumulate({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
  if (at >= sheets.length) return <Shown figures={sum} />;
  return <SheetFigures key={sheets[at]} sheets={sheets} at={at} sum={sum} asOf={asOf} />;
}

/** A sheet's figures as it shows them now (or, asOf given, as it showed them at the end of that day, with that day
 *  as its today): its people (retired ones included), its due-total and its overdue-total (as its header shows
 *  them), per grade the due-totals of its people on that grade today (retired ones left out, as its summary shows
 *  them), and per status how many of its claims have it. */
function SheetFigures({ sheets, at, sum, asOf }: { sheets: string[]; at: number; sum: Figures; asOf: string }) {
  const sheetId = sheets[at];
  const people = useNow<Person[]>(sheetId, 'people', asOf).data ?? [];
  const claims = useNow<Claim[]>(sheetId, 'claims', asOf).data ?? [];
  const rates = useNow<Rate[]>(sheetId, 'rates', asOf).data ?? [];
  const settings = useNow<Settings>(sheetId, 'settings', asOf).data;
  const sheetToday = useNow<Sheet>(sheetId, '', asOf).data?.today ?? '';
  const today = asOf !== '' && sheetToday !== '' ? asOf : sheetToday;
  const floor = floorOf(settings);
  const late = lateOf(settings, today, claims, people);
  const next: Figures = {
    names: [...sum.names, ...people.map((p) => [p.name, ...p.aliases])],
    dues: [...sum.dues, ...people.map((p) => personDueTotal(p, claims, rates, today, floor, late, settings?.cap ?? ''))],
